// Labels determine the filenames generated by starlight-llms-txt.
export const textExports = [
  { label: 'Get started', paths: ['getting-started', 'introduction'], slug: 'get-started' },
  { label: 'BBCode', paths: ['format-guides/bbcode'], slug: 'bbcode' },
  { label: 'HTML', paths: ['format-guides/html'], slug: 'html' },
  { label: 'MediaWiki', paths: ['format-guides/mediawiki'], slug: 'mediawiki' },
  { label: 'TextFormatter', paths: ['format-guides/textformatter'], slug: 'textformatter' },
  { label: 'Format guides', paths: ['format-guides', 'format-guides/**'], slug: 'format-guides' },
  { label: 'Customization', paths: ['customization', 'customization/**'], slug: 'customization' },
  { label: 'Concepts', paths: ['concepts', 'concepts/**'], slug: 'concepts' },
  { label: 'Migrating to Discourse', paths: ['migrating/**'], slug: 'migrating-to-discourse' },
  { label: 'Upgrading', paths: ['reference/upgrading'], slug: 'upgrading' },
  { label: 'Changelog', paths: ['changelog'], slug: 'changelog' },
];

/** @param {string} id */
export function textExportForPage(id) {
  return textExports.find(({ paths }) =>
    paths.some((path) => path.endsWith('/**') ? id.startsWith(path.slice(0, -2)) : id === path)
  );
}

/** @param {string} slug */
export function textExportHref(slug) {
  return `/_llms-txt/${slug}.txt`;
}
